class Solution:
    def visibleMountains(self, peaks: List[List[int]]) -> int:
        peaks.sort(key=lambda p: (p[0], -p[1]))
        st = []
        for x, y in peaks:
            while st and st[-1][1] < y and abs(x - st[-1][0]) <= y - st[-1][1]:
                st.pop()
            if st and st[-1][1] >= y and abs(x - st[-1][0]) <= st[-1][1] - y:
                continue
            st.append((x, y))
        return len(st)

