class Solution {
public:
    int visibleMountains(vector<vector<int>>& peaks) {
        sort(peaks.begin(), peaks.end(), [](auto& a, auto& b) {
            return a[0] != b[0] ? a[0] < b[0] : a[1] > b[1];
        });
        vector<pair<int,int>> st;
        for (auto& p : peaks) {
            int x = p[0], y = p[1];
            while (!st.empty() && st.back().second < y && abs(x - st.back().first) <= y - st.back().second)
                st.pop_back();
            if (!st.empty() && st.back().second >= y && abs(x - st.back().first) <= st.back().second - y)
                continue;
            st.push_back({x, y});
        }
        return st.size();
    }
};

