class Solution {
    public int visibleMountains(int[][] peaks) {
        Arrays.sort(peaks, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
        Deque<int[]> st = new ArrayDeque<>();
        for (int[] p : peaks) {
            int x = p[0], y = p[1];
            while (!st.isEmpty() && st.peek()[1] < y && Math.abs(x - st.peek()[0]) <= y - st.peek()[1])
                st.pop();
            if (!st.isEmpty() && st.peek()[1] >= y && Math.abs(x - st.peek()[0]) <= st.peek()[1] - y)
                continue;
            st.push(new int[]{x, y});
        }
        return st.size();
    }
}

